select jsonb_build_object('schemas',(select jsonb_agg(jsonb_build_object('name',nspname,'owner',pg_get_userbyid(nspowner),'acl',nspacl::text)order by nspname)from pg_namespace where nspname in('auth','storage','net','vault','extensions')),'relations',(select coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'name',c.relname,'kind',c.relkind,'owner',pg_get_userbyid(c.relowner),'acl',c.relacl::text)order by n.nspname,c.relname),'[]')from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in('auth','storage','net','vault')and c.relkind in('r','v','S')),'default_acl',(select coalesce(jsonb_agg(jsonb_build_object('role',pg_get_userbyid(d.defaclrole),'schema',n.nspname,'kind',d.defaclobjtype,'acl',d.defaclacl::text)order by n.nspname,d.defaclobjtype),'[]')from pg_default_acl d join pg_namespace n on n.oid=d.defaclnamespace where n.nspname in('auth','storage'))); 
